    "r90.a77f2d2326e3": "<span class=\"abadge\">{{svg1}}Nessuna quota, mai</span><span class=\"abadge\">{{svg2}}Uno dei 300 posti</span><span class=\"abadge\">Revisione umana prevista</span>",
