  "cues": [
    [
      3.4,
      7,
      "Solo i duri e i forti possono definirsi spartani."
    ],
    [
      8.3,
      10,
      "Solo i duri."
    ],
    [
      10.15,
      12.3,
      "Solo i forti."
    ],
    [
      39.6,
      43,
      "Marciamo."
    ],
    [
      44.3,
      48.6,
      "Per le nostre terre, per le nostre famiglie, per le nostre libertà."
    ],
    [
      50.5,
      52,
      "Marciamo."
    ],
    [
      54.5,
      57.9,
      "Daxos! Che piacevole sorpresa."
    ],
    [
      58.3,
      60.1,
      "Questa mattina è piena di sorprese, Leonida."
    ],
    [
      60.15,
      61,
      "Siamo stati ingannati."
    ],
    [
      61,
      62.2,
      "Non saranno più di poche centinaia."
    ],
    [
      62.3,
      63.8,
      "Questa sì che è una sorpresa."
    ],
    [
      63.85,
      64.7,
      "Silenzio!"
    ],
    [
      67.2,
      68.9,
      "Abbiamo saputo che Sparta era sul piede di guerra,"
    ],
    [
      69.9,
      71.3,
      "ed eravamo ansiosi di unire le forze."
    ],
    [
      71.8,
      76.4,
      "Se è sangue quello che cercate, siete i benvenuti tra noi."
    ],
    [
      76.6,
      79.3,
      "Portate solo questo pugno di soldati contro Serse?"
    ],
    [
      80,
      83.1,
      "Vedo che avevo torto a sperare che l'impegno di Sparta eguagliasse almeno il nostro."
    ],
    [
      84.6,
      85.7,
      "Non è così?"
    ],
    [
      88,
      89.4,
      "Tu, laggiù!"
    ],
    [
      90.1,
      91.2,
      "Qual è la tua professione?"
    ],
    [
      91.9,
      93.9,
      "Sono un vasaio... signore."
    ],
    [
      94.7,
      97.4,
      "E tu, Arcade!"
    ],
    [
      97.8,
      99,
      "Qual è la tua professione?"
    ],
    [
      99.3,
      100.5,
      "Scultore, signore."
    ],
    [
      102.8,
      103.7,
      "Tu?"
    ],
    [
      104,
      105.2,
      "Fabbro."
    ],
    [
      110.3,
      113.2,
      "Spartani! Qual è la vostra professione?!"
    ],
    [
      113.6,
      119.6,
      "HA-OOH! HA-OOH! HA-OOH!"
    ],
    [
      120.1,
      124.3,
      "Vedi, vecchio amico? Ho portato più soldati di te."
    ]
  ],
